import { GUIDE_CARDS } from './cards.js'
import { START_HERE, resolveGuideSlug } from './topics.js'

/**
 * Small guide index for lists, related links and the guides page: titles, topics and images only, no article text,
 * so pages that merely link to guides do not download every guide. The full guide loads on its own page.
 * GUIDE_CARDS is generated by scripts/gen-guides-index.mjs.
 */
export { GUIDE_CARDS }

export function getCard(slug) {
  return GUIDE_CARDS.find((c) => c.slug === slug) || null
}

/** A card for any slug, old or new (used by "related guides" lists). */
export function guideCard(slug) {
  const c = getCard(resolveGuideSlug(slug))
  return c ? { slug: c.slug, href: `/guides/${c.slug}`, title: c.title, description: c.excerpt, image: c.heroImage, lang: c.lang } : null
}

/** Other guides on the same topic and language first, then the start-here guides; never the guide itself. */
export function relatedCards(slug, limit = 3) {
  const current = getCard(slug)
  const same = GUIDE_CARDS.filter((c) => c.slug !== slug && current && c.category === current.category && (c.lang || 'en') === (current.lang || 'en'))
  const rest = START_HERE.map(getCard).filter((c) => c && c.slug !== slug && !same.includes(c))
  return [...same, ...rest].slice(0, limit)
}
